<template><article class="card repair-card"><div><h3>{{repair.title}}</h3><p>{{repair.description}}</p><small>{{repair.type}} · {{repair.user?.nickname||'业主'}} · {{new Date(repair.created_at).toLocaleString()}}</small><p v-if="repair.handler"><small>处理人：{{repair.handler.nickname}}</small></p><div v-if="repair.rating" class="repair-feedback"><el-rate :model-value="repair.rating" disabled/><small v-if="repair.rework_reason" class="rework-reason">返工原因：{{repair.rework_reason}}</small></div></div><div class="repair-side"><RepairStatusBadge :status="repair.status"/><el-button v-if="isStaff&&next" size="small" type="primary" @click="advance">{{next.label}}</el-button><div v-if="canEvaluate" class="evaluate-box"><el-rate v-model="rating"/><el-input v-if="rating>0&&rating<REPAIR_RATING_PASS" v-model="reason" type="textarea" :rows="2" placeholder="请填写返工原因（1-3 分必填）"/><el-button size="small" type="primary" :disabled="!rating" @click="submitEvaluate">提交验收</el-button></div></div></article></template><script setup lang="ts">import{ref,computed}from'vue';import{ElMessage}from'element-plus';import type{Repair,RepairStatus}from'../../types';import{updateRepairStatus,evaluateRepair}from'../../api/repair';import{REPAIR_RATING_PASS}from'../../constants/repair';import{useAuth}from'../../hooks/useAuth';import{authStore}from'../../stores/authStore';import RepairStatusBadge from'./RepairStatusBadge.vue';const p=defineProps<{repair:Repair}>();const emit=defineEmits<{changed:[]}>();const{isStaff}=useAuth();const rating=ref(0),reason=ref('');const flow:Partial<Record<RepairStatus,{to:RepairStatus;label:string}>>={pending:{to:'processing',label:'开始处理'},assigned:{to:'processing',label:'开始处理'},processing:{to:'done',label:'提交完工'}};const next=computed(()=>flow[p.repair.status]);const canEvaluate=computed(()=>p.repair.status==='done'&&authStore.user?.id===p.repair.user_id);async function advance(){if(!next.value)return;try{await updateRepairStatus(p.repair.id,next.value.to);ElMessage.success(next.value.to==='done'?'已提交完工，等待业主验收':'工单状态已更新');emit('changed')}catch(e){ElMessage.error((e as Error).message)}}async function submitEvaluate(){if(rating.value<REPAIR_RATING_PASS&&!reason.value.trim()){ElMessage.warning('评分 1-3 分需填写返工原因');return}try{await evaluateRepair(p.repair.id,rating.value,rating.value<REPAIR_RATING_PASS?reason.value.trim():undefined);ElMessage.success(rating.value>=REPAIR_RATING_PASS?'验收通过，工单已关闭':'已退回物业返工');rating.value=0;reason.value='';emit('changed')}catch(e){ElMessage.error((e as Error).message)}}</script><style scoped>.repair-side{display:flex;flex-direction:column;align-items:flex-end;gap:10px}.repair-feedback{display:flex;align-items:center;gap:10px;margin-top:8px}.rework-reason{color:#b45309}.evaluate-box{display:grid;gap:8px;justify-items:end;min-width:220px}</style>
